/**
 * Document writers, asserted against the real generated bytes.
 *
 * The LabMat is re-opened with `exceljs` and read cell by cell; the CheckList
 * is unzipped and its `word/document.xml` inspected. What is tested is
 * therefore what Excel and Word will show, not what the builder intended —
 * the same discipline AD-12 established for the install assessment's `.docx`.
 *
 * The templates are read from disk here rather than through
 * `lib/quoting/templates.ts`, which fetches a Vite asset URL and needs a
 * browser. Keeping the writers pure over bytes is what makes that possible.
 */

import { readFileSync } from 'node:fs';
import { join } from 'node:path';
import { beforeAll, describe, expect, it } from 'vitest';
import JSZip from 'jszip';

import {
  CHECKLIST_PLACEHOLDERS,
  PM_CONTINGENCY_CODE,
  PM_LEVELS
} from '../../config/sapQuoteGeneratorModel';
import {
  computeTotals,
  costedPhases,
  createBlankQuote,
  defaultsForProjectType,
  formatPercent,
  resolveScope,
  type QuoteState
} from './sapQuoteGenerator';
import { LABMAT_LAYOUT, buildLabmat, planLabmatRows } from './sapQuoteLabmat';
import {
  buildChecklist,
  escapeXml,
  expandPlaceholderParagraph,
  inclusionBullets,
  mergeAdjacentRuns,
  stripProofingMarkers
} from './sapQuoteChecklist';

const TEMPLATES = join(__dirname, 'templates');
const LABMAT_TEMPLATE = readFileSync(join(TEMPLATES, 'blank-bia-labmat.xlsx'));
const CHECKLIST_TEMPLATE = readFileSync(join(TEMPLATES, 'blank-checklist.docx'));

function bytes(buffer: Buffer): ArrayBuffer {
  return buffer.buffer.slice(
    buffer.byteOffset,
    buffer.byteOffset + buffer.byteLength
  ) as ArrayBuffer;
}

const STATE: QuoteState = {
  ...createBlankQuote('2026-08-05'),
  solutionArchitect: 'Mike Hobson',
  ticket: '2437170',
  client: 'Broder Group & Co',
  contactName: 'A Contact',
  contactEmail: 'a.contact@example.com',
  productStack: 'SAP Crystal Server',
  projectType: 'install',
  pricingBasis: 'Fixed',
  ...defaultsForProjectType('install'),
  hours: {
    'DI-BIA-SAP-CRY-DES-CONNECT': 0.5,
    'DI-BIA-SAP-CRY-DES-SOFTWARE': 1.5,
    'DI-BIA-SAP-CRY-BLD-MIGR-INSTALL': 7.5,
    'DI-BIA-SAP-CRY-BLD-MIGR-CONFIG': 7.5,
    'DI-BIA-SAP-CRY-BLD-MIGRATION': 7.5,
    'DI-BIA-SAP-CRY-UA-TESTING': 3.75,
    'DI-BIA-SAP-CRY-TRN-CLOUDCARE': 1
  },
  activity: { 'DI-BIA-SAP-CRY-BLD-MIGRATION': 'Initial and Go Live migrations' }
};

const TOTALS = computeTotals(STATE);

// ══════════════════════════════════════════════════════════════════════
// LabMat
// ══════════════════════════════════════════════════════════════════════

describe('LabMat row plan', () => {
  const rows = planLabmatRows(STATE, TOTALS);

  it('starts at the template body row', () => {
    expect(rows[0].row).toBe(LABMAT_LAYOUT.firstBodyRow);
  });

  it('numbers rows consecutively', () => {
    rows.forEach((row, i) => {
      expect(row.row).toBe(LABMAT_LAYOUT.firstBodyRow + i);
    });
  });

  it('stays inside the range that gets cleared', () => {
    expect(rows[rows.length - 1].row).toBeLessThanOrEqual(LABMAT_LAYOUT.lastClearedRow);
  });

  it('leads each phase with a total row and no product code', () => {
    for (const row of rows.filter((r) => r.isPhaseTotal)) {
      expect(row.code).toBe('');
      expect(row.description).toBe('');
    }
  });

  it('writes the stack name against every costed product', () => {
    for (const row of rows.filter((r) => !r.isPhaseTotal && r.code.startsWith('DI-BIA-SAP'))) {
      expect(row.stack).toBe(STATE.productStack);
    }
  });

  it('omits products with no hours', () => {
    expect(rows.some((r) => r.code === 'DI-BIA-SAP-CRY-DES-WORKSHOP')).toBe(false);
    expect(rows.every((r) => r.isPhaseTotal || r.hours > 0)).toBe(true);
  });

  it('includes derived contingency lines', () => {
    const contingency = rows.find((r) => r.code === 'DI-BIA-SAP-CRY-BLD-CONTINGENCY');
    expect(contingency).toBeDefined();
    expect(contingency!.hours).toBeCloseTo(4.5, 10);
  });

  it('ends with the PM phase, its line and its contingency', () => {
    const tail = rows.slice(-3);
    expect(tail[0].isPhaseTotal).toBe(true);
    expect(tail[0].stack).toBe('Data-Insights-BIA-Project-Management');
    expect(tail[1].code).toBe(TOTALS.pmProductCode);
    expect(tail[2].code).toBe(PM_CONTINGENCY_CODE);
  });

  it('foots the phase totals to the grand total', () => {
    const phaseHours = rows
      .filter((r) => r.isPhaseTotal)
      .reduce((n, r) => n + r.hours, 0);
    expect(phaseHours).toBeCloseTo(TOTALS.grandHours, 8);
  });

  it('has each phase total equal to the sum of its own lines', () => {
    let current: (typeof rows)[number] | undefined;
    let running = 0;
    const checks: Array<[number, number]> = [];
    for (const row of rows) {
      if (row.isPhaseTotal) {
        if (current) checks.push([current.hours, running]);
        current = row;
        running = 0;
      } else {
        running += row.hours;
      }
    }
    if (current) checks.push([current.hours, running]);
    for (const [total, sum] of checks) expect(total).toBeCloseTo(sum, 8);
  });

  it('omits the PM rows entirely when there is nothing to cost', () => {
    const empty = createBlankQuote('2026-08-05');
    expect(planLabmatRows(empty, computeTotals(empty))).toEqual([]);
  });

  it('omits the PM contingency row on target price', () => {
    const target: QuoteState = { ...STATE, pricingBasis: 'Target' };
    const plan = planLabmatRows(target, computeTotals(target));
    expect(plan.some((r) => r.code === PM_CONTINGENCY_CODE)).toBe(false);
    expect(plan.some((r) => r.code.endsWith('-TM'))).toBe(true);
  });
});

describe('generated LabMat workbook', () => {
  let sheet: import('exceljs').Worksheet;

  beforeAll(async () => {
    const out = await buildLabmat(bytes(LABMAT_TEMPLATE), STATE, TOTALS);
    const ExcelJS = await import('exceljs');
    const workbook = new ExcelJS.Workbook();
    await workbook.xlsx.load(out);
    sheet = workbook.getWorksheet(LABMAT_LAYOUT.sheet)!;
  });

  it('keeps the LabMat sheet', () => {
    expect(sheet).toBeDefined();
  });

  it('fills the header block', () => {
    const h = LABMAT_LAYOUT.header;
    expect(sheet.getCell(h.solutionArchitect).value).toBe('Mike Hobson');
    expect(sheet.getCell(h.date).value).toBe('2026-08-05');
    expect(sheet.getCell(h.client).value).toBe('Broder Group & Co');
    expect(sheet.getCell(h.ticket).value).toBe('2437170');
    expect(sheet.getCell(h.totalServicePrice).value).toBe(TOTALS.grandValue);
  });

  it('writes the total unrounded', () => {
    expect(sheet.getCell(LABMAT_LAYOUT.header.totalServicePrice).value).toBeCloseTo(
      6177.6,
      6
    );
  });

  it('writes every planned row into the right columns', () => {
    const { columns } = LABMAT_LAYOUT;
    for (const plan of planLabmatRows(STATE, TOTALS)) {
      expect(sheet.getCell(plan.row, columns.stack).value).toBe(plan.stack);
      expect(sheet.getCell(plan.row, columns.hours).value).toBeCloseTo(plan.hours, 8);
      expect(sheet.getCell(plan.row, columns.days).value).toBeCloseTo(plan.days, 8);
      expect(sheet.getCell(plan.row, columns.value).value).toBeCloseTo(plan.value, 6);
      if (!plan.isPhaseTotal) {
        expect(sheet.getCell(plan.row, columns.code).value).toBe(plan.code);
        expect(sheet.getCell(plan.row, columns.description).value).toBe(plan.description);
      }
    }
  });

  it('carries the activity note across', () => {
    const plan = planLabmatRows(STATE, TOTALS).find(
      (r) => r.code === 'DI-BIA-SAP-CRY-BLD-MIGRATION'
    )!;
    expect(sheet.getCell(plan.row, LABMAT_LAYOUT.columns.activity).value).toBe(
      'Initial and Go Live migrations'
    );
  });

  it('bolds the phase total rows', () => {
    for (const plan of planLabmatRows(STATE, TOTALS).filter((r) => r.isPhaseTotal)) {
      expect(sheet.getCell(plan.row, LABMAT_LAYOUT.columns.stack).font?.bold).toBe(true);
      expect(sheet.getCell(plan.row, LABMAT_LAYOUT.columns.value).font?.bold).toBe(true);
    }
  });

  it('leaves nothing below the last written row', () => {
    const last = planLabmatRows(STATE, TOTALS).slice(-1)[0].row;
    for (let row = last + 1; row <= LABMAT_LAYOUT.lastClearedRow; row += 1) {
      expect(sheet.getCell(row, LABMAT_LAYOUT.columns.stack).value).toBeNull();
      expect(sheet.getCell(row, LABMAT_LAYOUT.columns.value).value).toBeNull();
    }
  });

  /*
   * The house style is the template's, so what matters is that filling it
   * did not disturb the formatting. 316 merges and the currency format on
   * the value column are the load-bearing parts.
   */
  it('preserves the template merges and number formats', () => {
    expect(Object.keys((sheet as unknown as { _merges: object })._merges)).toHaveLength(316);
    expect(sheet.getCell('AA9').numFmt).toBe('"£"#,##0.00');
    expect(sheet.getCell('U9').numFmt).toBe('0.00');
    expect(sheet.getCell(LABMAT_LAYOUT.header.totalServicePrice).numFmt).toBe(
      '"£"#,##0.00'
    );
  });

  it('rejects a workbook with no LabMat sheet', async () => {
    const ExcelJS = await import('exceljs');
    const stranger = new ExcelJS.Workbook();
    stranger.addWorksheet('Sheet1');
    const buffer = (await stranger.xlsx.writeBuffer()) as ArrayBuffer;
    await expect(buildLabmat(buffer, STATE, TOTALS)).rejects.toThrow(/no "LabMat" sheet/);
  });
});

