describe('XML helpers', () => {
  it('escapes the five XML entities', () => {
    expect(escapeXml(`a & b < c > d " e ' f`)).toBe(
      'a &amp; b &lt; c &gt; d &quot; e &apos; f'
    );
  });

  it('strips proofing and bookmark markers', () => {
    const xml = '<w:p><w:proofErr w:type="spellStart"/><w:bookmarkStart w:id="1"/>x<w:bookmarkEnd w:id="1"/></w:p>';
    expect(stripProofingMarkers(xml)).toBe('<w:p>x</w:p>');
  });

  it('merges runs split across more than two elements', () => {
    const xml =
      '<w:r><w:t>&lt;&lt;con</w:t></w:r><w:r><w:t>tact_</w:t></w:r><w:r><w:rPr><w:b/></w:rPr><w:t>name&gt;&gt;</w:t></w:r>';
    expect(mergeAdjacentRuns(xml)).toContain('&lt;&lt;contact_name&gt;&gt;');
  });

  it('expands a placeholder paragraph into one paragraph per bullet', () => {
    const xml =
      '<w:body><w:p><w:pPr><w:numPr><w:ilvl w:val="0"/><w:numId w:val="3"/></w:numPr></w:pPr><w:r><w:rPr><w:sz w:val="20"/></w:rPr><w:t>&lt;&lt;dependencies&gt;&gt;</w:t></w:r></w:p></w:body>';
    const out = expandPlaceholderParagraph(xml, '<<dependencies>>', [
      { text: 'One.', level: 0 },
      { text: 'Two.', level: 1 }
    ]);
    expect(out).not.toContain('&lt;&lt;dependencies&gt;&gt;');
    expect(out.match(/<w:t xml:space="preserve">/g)).toHaveLength(2);
    // Each bullet keeps the template's numbering binding and run properties.
    expect(out.match(/<w:numId w:val="3"\/>/g)).toHaveLength(2);
    expect(out.match(/<w:sz w:val="20"\/>/g)).toHaveLength(2);
    expect(out).toContain('<w:ilvl w:val="1"/>');
  });

  it('collapses an empty list to a single empty paragraph', () => {
    const xml = '<w:p><w:pPr><w:ilvl w:val="0"/></w:pPr><w:r><w:t>&lt;&lt;assumptions&gt;&gt;</w:t></w:r></w:p>';
    const out = expandPlaceholderParagraph(xml, '<<assumptions>>', []);
    expect(out).not.toContain('&lt;&lt;assumptions&gt;&gt;');
    expect(out).toContain('<w:t></w:t>');
  });

  it('escapes bullet text as it expands', () => {
    const xml = '<w:p><w:pPr/><w:r><w:t>&lt;&lt;assumptions&gt;&gt;</w:t></w:r></w:p>';
    const out = expandPlaceholderParagraph(xml, '<<assumptions>>', [
      { text: 'Firewalls & ports <check>', level: 0 }
    ]);
    expect(out).toContain('Firewalls &amp; ports &lt;check&gt;');
  });
});

describe('inclusion bullets', () => {
  const bullets = inclusionBullets(STATE, TOTALS);

  it('nests scope items beneath their category', () => {
    const platform = bullets.findIndex((b) => b.text === 'SAP Platform Implementation Services');
    expect(platform).toBeGreaterThanOrEqual(0);
    expect(bullets[platform].level).toBe(0);
    expect(bullets[platform + 1].level).toBe(1);
  });

  it('ends with the PM tier and its deliverables', () => {
    const level = PM_LEVELS.find((l) => l.id === TOTALS.pmLevel)!;
    const index = bullets.findIndex((b) => b.text === level.label);
    expect(index).toBeGreaterThanOrEqual(0);
    expect(bullets[index].level).toBe(0);
    expect(bullets.slice(index + 1).map((b) => b.text)).toEqual(level.deliverables);
  });

  it('lists every resolved scope item', () => {
    const texts = bullets.map((b) => b.text);
    for (const category of resolveScope(STATE)) {
      expect(texts).toContain(category.label);
      for (const item of category.items) expect(texts).toContain(item);
    }
  });

  it('still carries a PM tier when nothing is in scope', () => {
    const bare: QuoteState = {
      ...STATE,
      inScope: {},
      customScope: { platform: [], training: [], other: [] }
    };
    expect(inclusionBullets(bare, TOTALS).length).toBeGreaterThan(0);
  });
});

describe('generated CheckList document', () => {
  let xml: string;

  beforeAll(async () => {
    const out = await buildChecklist(bytes(CHECKLIST_TEMPLATE), STATE, TOTALS);
    const zip = await JSZip.loadAsync(out);
    xml = await zip.file('word/document.xml')!.async('string');
  });

  it('leaves no placeholder behind', () => {
    for (const placeholder of Object.values(CHECKLIST_PLACEHOLDERS)) {
      expect(xml, placeholder).not.toContain(escapeXml(placeholder));
      expect(xml, placeholder).not.toContain(placeholder);
    }
  });

  it('fills the overview table', () => {
    expect(xml).toContain('2437170');
    expect(xml).toContain('Broder Group &amp; Co');
    expect(xml).toContain('A Contact');
    expect(xml).toContain('a.contact@example.com');
    expect(xml).toContain('Fixed');
    expect(xml).toContain(formatPercent(TOTALS.pmRate));
  });

  it('escapes an ampersand in the client name rather than emitting raw XML', () => {
    expect(xml).not.toMatch(/Broder Group & Co/);
  });

  it('writes every dependency, assumption and exclusion', () => {
    for (const text of [...STATE.dependencies, ...STATE.assumptions, ...STATE.exclusions]) {
      expect(xml, text).toContain(escapeXml(text));
    }
  });

  it('writes the inclusions with their categories', () => {
    for (const bullet of inclusionBullets(STATE, TOTALS)) {
      expect(xml, bullet.text).toContain(escapeXml(bullet.text));
    }
  });

  it('leaves the introduction empty, since the brief step is not built', () => {
    // The placeholder resolves to nothing rather than to literal text — a
    // blank section the consultant fills in, not a stray token. See AD-14.
    expect(xml).not.toContain('project_brief');
  });

  it('accepts a brief when one is supplied', async () => {
    const out = await buildChecklist(bytes(CHECKLIST_TEMPLATE), STATE, TOTALS, {
      brief: 'First line.\nSecond line.'
    });
    const zip = await JSZip.loadAsync(out);
    const withBrief = await zip.file('word/document.xml')!.async('string');
    expect(withBrief).toContain('First line.');
    expect(withBrief).toContain('<w:br/>');
    expect(withBrief).toContain('Second line.');
  });

  /*
   * Compares document parts, not archive entries: re-zipping adds explicit
   * directory entries (`word/`) that the original does not have. Word
   * ignores them, and asserting on them would pin a JSZip implementation
   * detail rather than the thing that matters — that no part was lost.
   */
  it('stays a valid docx with every part intact', async () => {
    const out = await buildChecklist(bytes(CHECKLIST_TEMPLATE), STATE, TOTALS);
    const original = await JSZip.loadAsync(bytes(CHECKLIST_TEMPLATE));
    const rebuilt = await JSZip.loadAsync(out);
    const parts = (zip: JSZip) =>
      Object.values(zip.files)
        .filter((f) => !f.dir)
        .map((f) => f.name)
        .sort();
    expect(parts(rebuilt)).toEqual(parts(original));
  });

  it('keeps the template styles part untouched', async () => {
    const out = await buildChecklist(bytes(CHECKLIST_TEMPLATE), STATE, TOTALS);
    const original = await JSZip.loadAsync(bytes(CHECKLIST_TEMPLATE));
    const rebuilt = await JSZip.loadAsync(out);
    expect(await rebuilt.file('word/styles.xml')!.async('string')).toBe(
      await original.file('word/styles.xml')!.async('string')
    );
    expect(await rebuilt.file('word/numbering.xml')!.async('string')).toBe(
      await original.file('word/numbering.xml')!.async('string')
    );
  });

  it('rejects a zip that is not a Word document', async () => {
    const zip = new JSZip();
    zip.file('hello.txt', 'not a docx');
    const buffer = await zip.generateAsync({ type: 'arraybuffer' });
    await expect(buildChecklist(buffer, STATE, TOTALS)).rejects.toThrow(
      /no word\/document\.xml/
    );
  });
});

describe('both documents agree', () => {
  it('quotes the same figure in the spreadsheet and the scope', async () => {
    const plan = planLabmatRows(STATE, TOTALS);
    const phaseHours = plan.filter((r) => r.isPhaseTotal).reduce((n, r) => n + r.hours, 0);
    expect(phaseHours).toBeCloseTo(TOTALS.grandHours, 8);

    const out = await buildChecklist(bytes(CHECKLIST_TEMPLATE), STATE, TOTALS);
    const zip = await JSZip.loadAsync(out);
    const xml = await zip.file('word/document.xml')!.async('string');
    // The CheckList states the PM rate; the LabMat prices it. If the tier
    // moved in one and not the other, the documents would contradict.
    expect(xml).toContain(formatPercent(TOTALS.pmRate));
    expect(plan.some((r) => r.code === TOTALS.pmProductCode)).toBe(true);
  });

  it('names every costed phase in the spreadsheet', () => {
    const planned = planLabmatRows(STATE, TOTALS)
      .filter((r) => r.isPhaseTotal)
      .map((r) => r.stack);
    for (const phase of costedPhases(TOTALS.phases)) {
      expect(planned).toContain(phase.name);
    }
  });
});
